        "body": "교섭권만 주고 체결은 총회 인준에 맡기면 교섭 상대방은 합의해도 그것이 최종인지 알 수 없어 진지한 협상이 어려워진다. 제29조제1항이 두 권한을 함께 대표자에게 둔 것은 교섭의 결과가 구속력을 갖도록 하려는 것이다. 다만 조합 내부 민주성도 무시할 수 없어, 실무에서는 인준 절차를 두되 그것이 체결권을 전면적으로 박탈하는 정도에 이르지 않는 선에서 조정된다. 제16조제1항제3호가 단체협약을 총회 의결사항으로 든 것과 제29조제1항이 어떻게 함께 서는지가 이 논점의 핵심이다."
